"""Fit a small ML world model using data generated by the synthetic simulator.

IMPORTANT: The first simulator is deliberately linear. Linear regression therefore
nearly reproduces its equation. This validates integration, NOT novelty or a field
performance claim. The world model is *not* trained on equipment-degradation data.
"""

import numpy as np
from sklearn.linear_model import LinearRegression
from sklearn.metrics import mean_absolute_error

from simulator import next_step

FEATURES = ("temperature_c", "ambient_c", "process_demand_kw", "heater_input_kw")


def _make_examples(count: int, rng: np.random.Generator):
    temperatures = rng.uniform(54.0, 66.0, count)
    ambient = rng.uniform(8.0, 40.0, count)
    process = rng.uniform(0.0, 9.0, count)
    heater = rng.uniform(0.0, 12.0, count)
    x = np.column_stack((temperatures, ambient, process, heater))
    changes = np.array(
        [
            next_step(t, a, d, p)[0] - t
            for t, a, d, p in x
        ],
        dtype=float,
    )
    return x, changes


def train_world_model(seed: int = 20261020):
    """Return (trained linear model, synthetic held-out MAE in °C per step)."""
    rng = np.random.default_rng(seed)
    x_train, y_train = _make_examples(6000, rng)
    x_test, y_test = _make_examples(1200, rng)

    model = LinearRegression()
    model.fit(x_train, y_train)
    test_mae = mean_absolute_error(y_test, model.predict(x_test))
    return model, float(test_mae)


def predict_next_temperature(model, temp_c, ambient_c, process_kw, heater_kw):
    x = np.array([[temp_c, ambient_c, process_kw, heater_kw]], dtype=float)
    return float(temp_c + model.predict(x)[0])
